"// ==========================================
// 1. 在下方的括號 [] 內填寫道具的 ID，使用逗號隔開
// 例如: [1, 2, 5, 10]
// ==========================================
const chance_80_items = [142, 143, 144, 145, 146, 147, 148, 149, 150, 151]; // 填入 80% 機率出現的道具 ID
const chance_50_items = [153, 154]; // 填入 50% 機率出現的道具 ID
const chance_20_items = [117, 118, 119, 120, 121, 122, 123, 124, 125, 132, 133, 134, 135, 136, 137, 138, 139, 140, ]; // 填入 20% 機率出現的道具 ID

let goods = [];
let all_possible_ids = []; 

// 將所有填寫的 ID 收集到總池子裡，方便缺貨時隨機抽取補齊
all_possible_ids = all_possible_ids.concat(chance_80_items, chance_50_items, chance_20_items);

// ==========================================
// 2. 機率判定 (每個道具獨立判定一次)
// ==========================================
for (const id of chance_80_items) {
    if (Math.random() * 100 < 80 && $dataItems[id]) goods.push($dataItems[id]);
}
for (const id of chance_50_items) {
    if (Math.random() * 100 < 50 && $dataItems[id]) goods.push($dataItems[id]);
}
for (const id of chance_20_items) {
    if (Math.random() * 100 < 20 && $dataItems[id]) goods.push($dataItems[id]);
}

// ==========================================
// 3. 確保商店剛好有 8 個商品 (多退少補，允許重複)
// ==========================================
const targetCount = 8;

// 情況 A：如果抽中的商品超過 8 個 -> 隨機打亂後，只保留前 8 個
if (goods.length > targetCount) {
    goods.sort(() => Math.random() - 0.5);
    goods = goods.slice(0, targetCount);
}

// 情況 B：如果抽中的商品少於 8 個 -> 從總池子裡隨機抽道具補滿 (會出現重複道具)
if (all_possible_ids.length > 0) {
    while (goods.length < targetCount) {
        let randomId = all_possible_ids[Math.floor(Math.random() * all_possible_ids.length)];
        if ($dataItems[randomId]) {
            goods.push($dataItems[randomId]);
        }
    }
}

// 返回最終 8 個商品的列表給系統
return goods;"

"// ==========================================
// 1. 在下方的括號 [] 內填寫道具的 ID，使用逗號隔開
// 例如: [1, 2, 5, 10]
// ==========================================
const chance_80_items = [170, 173, 176]; // 填入 80% 機率出現的道具 ID
const chance_50_items = [171, 174, 175]; // 填入 50% 機率出現的道具 ID
const chance_20_items = [172, 177, 178, 179]; // 填入 20% 機率出現的道具 ID

let goods = [];
let chosen_ids = []; // 記錄已選中的 ID，用來防止重複

// ==========================================
// 2. 機率判定 (每個道具獨立判定一次)
// ==========================================
function rollItem(id, chance) {
  if (Math.random() * 100 < chance && $dataItems[id] && !chosen_ids.includes(id)) {
    goods.push($dataItems[id]);
    chosen_ids.push(id);
  }
}

for (const id of chance_80_items) rollItem(id, 80);
for (const id of chance_50_items) rollItem(id, 50);
for (const id of chance_20_items) rollItem(id, 20);

// ==========================================
// 3. 確保商店剛好有指定數量的商品 (多退少補，不重複)
// ==========================================
const targetCount = 3; // 想要幾個商品就改這裡

// 情況 A：抽中的商品超過目標 -> 隨機打亂後只保留前 N 個
if (goods.length > targetCount) {
  goods.sort(() => Math.random() - 0.5);
  goods = goods.slice(0, targetCount);
}

// 情況 B：抽中的商品不足 -> 從尚未選中的道具裡隨機補滿 (不重複)
if (goods.length < targetCount) {
  // 收集所有還沒被選中的 ID
  let remaining = [].concat(chance_80_items, chance_50_items, chance_20_items)
                    .filter(id => $dataItems[id] && !chosen_ids.includes(id));

  // 隨機打亂剩餘池
  remaining.sort(() => Math.random() - 0.5);

  // 依序補滿，補到目標數量或池子抽乾為止
  while (goods.length < targetCount && remaining.length > 0) {
    let id = remaining.shift();
    goods.push($dataItems[id]);
    chosen_ids.push(id);
  }
}

return goods;"

